begin;
create temp table community_results(check_name text,passed boolean);
do $test$
declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();staff uuid;
 pid uuid;cid uuid;commentid uuid;replyid uuid;rid uuid;nonce uuid:=gen_random_uuid();result jsonb;result2 jsonb;denied boolean;lastrow jsonb;conv uuid;mark integer;idx integer;
begin
 select user_id into staff from private_website_lab.member_roles where role='full_admin' limit 1;
 insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) select x,'community-'||x||'@example.invalid',now(),jsonb_build_object('full_name','Synthetic community member') from unnest(array[a,b,outsider])x;
 perform set_config('request.jwt.claim.sub',a::text,true);
 result:=public.website_lab_community('publish',jsonb_build_object('kind','question','body','How do we check a SQL query plan safely?','topics',jsonb_build_array('SQL'),'client_nonce',nonce));pid:=(result->>'post_id')::uuid;
 perform public.website_lab_community('publish',jsonb_build_object('kind','question','body','Retried submission must not duplicate this post.','client_nonce',nonce));
 if (select count(*) from private_website_lab.market_posts where author_id=a)<>1 then raise exception 'Post retry duplicated content';end if;
 perform set_config('request.jwt.claim.sub',b::text,true);
 perform public.website_lab_community('comment',jsonb_build_object('post_id',pid,'body','Start with EXPLAIN and inspect indexes.','client_nonce',gen_random_uuid()));
 select id into commentid from private_website_lab.market_comments where post_id=pid;
 perform public.website_lab_community('comment',jsonb_build_object('post_id',pid,'parent_id',commentid,'body','An additional reference for the discussion.','client_nonce',gen_random_uuid()));
 select id into replyid from private_website_lab.market_comments where parent_id=commentid;
 denied:=false;begin perform public.website_lab_community('comment',jsonb_build_object('post_id',pid,'parent_id',replyid,'body','This nesting is too deep.','client_nonce',gen_random_uuid()));exception when raise_exception then denied:=true;end;if not denied then raise exception 'Deep nesting accepted';end if;
 perform public.website_lab_community('like',jsonb_build_object('post_id',pid));perform public.website_lab_community('like',jsonb_build_object('post_id',pid));
 perform public.website_lab_community('bookmark',jsonb_build_object('post_id',pid));perform public.website_lab_community('follow',jsonb_build_object('member_id',a));
 result:=public.website_lab_community('feed','{"view":"following","q":"SQL"}');
 if jsonb_array_length(result->'rows')<>1 or result->'rows'->0->>'likes'<>'1' or result->'rows'->0->>'comments'<>'2' or result->'rows'->0->>'bookmarked'<>'true' then raise exception 'Feed interactions or search incorrect: %',result;end if;
 result:=public.website_lab_community('post',jsonb_build_object('post_id',pid));if jsonb_array_length(result->'comments')<>2 or result->'post'?'client_nonce' then raise exception 'Post projection incorrect';end if;
 if not exists(select 1 from private_website_lab.notifications where recipient_id=a and event_key like 'market-comment:%') then raise exception 'Comment notification missing';end if;
 insert into community_results values('posts and comments are idempotent, nesting bounded, search/follow/bookmark/reaction views and notifications work',true);
 denied:=false;begin perform public.website_lab_community('publish',jsonb_build_object('kind','collaborators','body','Try recruiting without an approved active Lab.','client_nonce',gen_random_uuid()));exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Ungoverned recruitment post accepted';end if;
 if exists(select 1 from public.website_project_teams where coordinator_id in(a,b,outsider)) then raise exception 'Community created a Lab';end if;
 insert into community_results values('ordinary community posting does not create Labs or bypass recruitment authority',true);
 -- Opt-out blocks message requests; opt-in still requires the recipient to accept.
 perform set_config('request.jwt.claim.sub',a::text,true);denied:=false;
 begin perform public.website_lab_community('message_request',jsonb_build_object('member_id',b,'body','May I ask a question about your public skills?','client_nonce',gen_random_uuid()));exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Contact opt-out ignored';end if;
 perform set_config('request.jwt.claim.sub',b::text,true);perform public.website_lab_market('preferences','{"discoverable":true,"contactable":true}');
 perform set_config('request.jwt.claim.sub',a::text,true);nonce:=gen_random_uuid();
 result:=public.website_lab_community('message_request',jsonb_build_object('member_id',b,'body','May I ask a question about your public skills?','client_nonce',nonce));conv:=(result->>'conversation_id')::uuid;
 perform public.website_lab_community('message_request',jsonb_build_object('member_id',b,'body','Retried request','client_nonce',nonce));
 if (select count(*) from private_website_lab.market_messages where conversation_id=conv)<>1 then raise exception 'Message request duplicated';end if;
 denied:=false;begin perform public.website_lab_community('message',jsonb_build_object('conversation_id',conv,'body','Must wait for acceptance','client_nonce',gen_random_uuid()));exception when raise_exception then denied:=true;end;if not denied then raise exception 'Request sender continued without acceptance';end if;
 denied:=false;begin perform public.website_lab_community('message_decision',jsonb_build_object('conversation_id',conv,'enabled',true));exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Sender self-accepted message request';end if;
 perform set_config('request.jwt.claim.sub',b::text,true);result:=public.website_lab_community('conversations');if result->'rows'->0->>'unread'<>'1' then raise exception 'Unread request missing';end if;
 perform public.website_lab_community('message_decision',jsonb_build_object('conversation_id',conv,'enabled',true));
 nonce:=gen_random_uuid();perform public.website_lab_community('message',jsonb_build_object('conversation_id',conv,'body','Yes, happy to discuss this public topic.','client_nonce',nonce));perform public.website_lab_community('message',jsonb_build_object('conversation_id',conv,'body','Duplicate','client_nonce',nonce));
 result:=public.website_lab_community('conversation',jsonb_build_object('conversation_id',conv));if jsonb_array_length(result->'messages')<>2 or result->'messages'->0?'client_nonce' then raise exception 'Message projection or replay incorrect';end if;
 result:=public.website_lab_community('conversations');if result->'rows'->0->>'unread'<>'0' then raise exception 'Read marker incorrect';end if;
 insert into community_results values('contact preferences, request consent, private messages, replay and unread indicators work',true);
 select id into rid from private_website_lab.market_messages where conversation_id=conv and sender_id=a;
 perform public.website_lab_community('report',jsonb_build_object('kind','message','target_id',rid,'reason','Synthetic reported message for privacy assertion'));
 perform set_config('request.jwt.claim.sub',outsider::text,true);denied:=false;begin perform public.website_lab_community('conversation',jsonb_build_object('conversation_id',conv));exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Outsider read private messages';end if;
 denied:=false;begin perform public.website_lab_community('report',jsonb_build_object('kind','message','target_id',rid,'reason','Outsider cannot inspect or report private content'));exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Outsider reported private message';end if;
 denied:=false;begin perform public.website_lab_community('reports');exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Ordinary member read moderation queue';end if;
 perform set_config('request.jwt.claim.sub',staff::text,true);result:=public.website_lab_community('reports');
 if not exists(select 1 from jsonb_array_elements(result->'rows')r where r->>'kind'='message' and r->'snapshot'->>'body'='May I ask a question about your public skills?') then raise exception 'Reported excerpt unavailable to moderator';end if;
 denied:=false;begin perform public.website_lab_community('conversation',jsonb_build_object('conversation_id',conv));exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Moderator acquired private conversation access';end if;
 perform set_config('request.jwt.claim.sub',b::text,true);perform public.website_lab_community('report',jsonb_build_object('kind','post','target_id',pid,'reason','Synthetic reported post moderation check'));
 select id into rid from private_website_lab.market_reports where target_id=pid and reporter_id=b;
 perform set_config('request.jwt.claim.sub',staff::text,true);perform public.website_lab_community('resolve_report',jsonb_build_object('report_id',rid,'enabled',true,'reason','Synthetic moderation decision and removal'));
 if private_website_lab.market_post_visible(pid,b) then raise exception 'Moderation removal failed';end if;
 insert into community_results values('outsiders and moderators cannot open private conversations; reports expose only selected excerpts and record review',true);
 perform set_config('request.jwt.claim.sub',b::text,true);perform public.website_lab_community('block',jsonb_build_object('member_id',a));
 perform set_config('request.jwt.claim.sub',a::text,true);
 denied:=false;begin perform public.website_lab_community('message',jsonb_build_object('conversation_id',conv,'body','Blocked contact should fail','client_nonce',gen_random_uuid()));exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Blocked contact sent message';end if;
 if exists(select 1 from private_website_lab.market_follows where follower_id=b and followed_id=a) then raise exception 'Blocking retained follow';end if;
 result:=public.website_lab_market('people',jsonb_build_object('q',b::text));if result->>'total'<>'0' then raise exception 'Blocked profile visible';end if;
 result:=public.website_lab_community('conversations');if jsonb_array_length(result->'rows')<>0 then raise exception 'Blocked conversation still listed';end if;
 perform set_config('request.jwt.claim.sub',b::text,true);perform public.website_lab_community('block',jsonb_build_object('member_id',a,'enabled',false));
 result:=public.website_lab_community('conversation',jsonb_build_object('conversation_id',conv));if result->'conversation'->>'state'<>'declined' then raise exception 'Unblock silently reopened consent';end if;
 insert into community_results values('blocking hides reciprocal discovery, stops contact and removes follows without silently reopening conversations',true);
 -- Scale fixtures deliberately use tied timestamps to test the UUID tiebreaker.
 insert into private_website_lab.market_posts(author_id,kind,body,topics,client_nonce,created_at) select a,'update','Scale check public post '||g,array['scale'],gen_random_uuid(),now()-interval '1 day' from generate_series(1,1025)g;
 perform set_config('request.jwt.claim.sub',a::text,true);
 result:=public.website_lab_community('feed','{"q":"Scale check public post"}');if jsonb_array_length(result->'rows')<>25 then raise exception 'Feed page not bounded';end if;
 lastrow:=result->'rows'->24;
 result2:=public.website_lab_community('feed',jsonb_build_object('q','Scale check public post','before_at',lastrow->>'created_at','before_id',lastrow->>'id'));
 if jsonb_array_length(result2->'rows')<>25 or exists(select 1 from jsonb_array_elements(result->'rows')x join jsonb_array_elements(result2->'rows')y on x->>'id'=y->>'id') then raise exception 'Feed cursor duplicated rows';end if;
 insert into private_website_lab.market_messages(conversation_id,sender_id,body,client_nonce,created_at) select conv,a,'Synthetic bounded message '||g,gen_random_uuid(),now()-interval '1 day' from generate_series(1,1000)g;
 result:=public.website_lab_community('conversation',jsonb_build_object('conversation_id',conv));lastrow:=result->'messages'->24;
 result2:=public.website_lab_community('conversation',jsonb_build_object('conversation_id',conv,'before_at',lastrow->>'created_at','before_id',lastrow->>'id'));
 if jsonb_array_length(result->'messages')<>25 or jsonb_array_length(result2->'messages')<>25 or exists(select 1 from jsonb_array_elements(result->'messages')x join jsonb_array_elements(result2->'messages')y on x->>'id'=y->>'id') then raise exception 'Message cursor duplicated or unbounded';end if;
 if has_table_privilege('authenticated','private_website_lab.market_messages','SELECT') or has_table_privilege('anon','private_website_lab.market_posts','SELECT') or has_function_privilege('anon','public.website_lab_community(text,jsonb)','EXECUTE') then raise exception 'Private data grants exposed';end if;
 insert into community_results values('1,025 posts and 1,000 messages have bounded stable cursor pages; private tables and anonymous RPC remain denied',true);
end $test$;
select * from community_results;
rollback;
